type PostId = string;

interface Post {
  id: PostId;
  entityVersion: number;
  type: 'text' | 'image' | 'video' | 'ad';
  authorId: string;
  body: string;
  createdAt: number;
  likeCount: number;
  viewerLiked: boolean;
  mediaUrl?: string;
}

interface FeedOrder {
  queryKey: string;
  rankRevision: number;
  orderedIds: PostId[];
  nextCursor: string | null;
}

interface LiveFeedEvent {
  eventId: string;
  sequence: number;
  resumeCursor: string;
  type: 'post-upserted' | 'post-deleted' | 'rank-invalidated';
  post?: Post;
  postId?: PostId;
  rankRevision?: number;
}

interface PendingReaction {
  commandId: string;
  postId: PostId;
  desiredLiked: boolean;
  basedOnVersion: number;
}

interface FeedState {
  entities: Record<PostId, Post>;
  order: FeedOrder | null;
  pendingLiveIds: PostId[];
  acceptedEventIds: Record<string, true>;
  resumeCursor: string | null;
  optimisticReactions: Record<PostId, PendingReaction>;
}
